insert into public.coaches (id, name_ar, name_en, title_ar, title_en, photo_url, bio_ar, bio_en, philosophy_ar, philosophy_en,
  specialties_ar, specialties_en, certifications_ar, certifications_en, achievements_ar, achievements_en,
  years_experience, students_trained, programs_count, satisfaction_rate, phone, email, is_primary, is_demo)
values ('c0ac0000-0000-4000-8000-000000000001', 'أمير سلامي', 'Amir Salami',
 'مدرب سباحة شخصي', 'Personal Swimming Coach',
 'https://images.unsplash.com/photo-1560090995-01632a28895b?auto=format&fit=crop&w=1000&q=80',
 'كابتن أمير سلامي مدرب سباحة شخصي يعمل مع الأطفال والمراهقين والكبار. يركّز على بناء الثقة في الماء أولاً ثم تطوير التقنية خطوة بخطوة، مع خطط تدريب واضحة تناسب مستوى وهدف كل متدرب. (نص تجريبي — سيتم استبداله بالسيرة الحقيقية)',
 'Captain Amir Salami is a personal swimming coach working with children, teenagers and adults. He focuses on building water confidence first, then developing technique step by step with clear plans that match each swimmer''s level and goal. (Demo text — to be replaced with the real biography)',
 'السباحة مهارة حياة قبل أن تكون رياضة. أؤمن أن كل شخص يستطيع التعلّم عندما يشعر بالأمان، ويتقدّم بسرعة عندما يفهم لماذا يؤدي كل حركة.',
 'Swimming is a life skill before it is a sport. I believe everyone can learn once they feel safe — and progress fast once they understand why each movement matters.',
 array['تعليم المبتدئين من الصفر','سباحة الأطفال','تصحيح الأساليب الأربعة','التحضير للمنافسات','التغلب على الخوف من الماء'],
 array['Teaching complete beginners','Kids swimming','Correcting all four strokes','Competition preparation','Overcoming fear of water'],
 array['شهادة مدرب سباحة (بيانات تجريبية)','شهادة إنقاذ وإسعافات أولية (بيانات تجريبية)','دورة تدريب الأطفال في الماء (بيانات تجريبية)'],
 array['Swimming coach certificate (demo data)','Lifeguard & first aid certificate (demo data)','Kids aquatic coaching course (demo data)'],
 array['تدريب فرق ناشئين للبطولات المحلية (بيانات تجريبية)','تطوير برنامج "الثقة بالماء" للمبتدئين (بيانات تجريبية)'],
 array['Coached junior squads for local championships (demo data)','Developed a Water Confidence program for beginners (demo data)'],
 10, 1200, 8, 98, '+20 100 000 0000', 'coach@example.com', true, true)
on conflict (id) do nothing;

