insert into public.lessons (id, title_ar, title_en, icon, image_url, description_ar, description_en, level, estimated_minutes, steps_ar, steps_en, tips_ar, tips_en, sort_order, is_demo) values
('e5500000-0000-4000-8000-000000000001','البداية','Getting Started','flag','https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1000&q=80',
 'ما الذي تحتاجه قبل أول نزول للماء وكيف تستعد ذهنياً وجسدياً.','What you need before your first time in the water and how to prepare mentally and physically.','beginner',20,
 array['جهّز أدواتك: مايوه ونظارة وغطاء رأس','قم بالإحماء على الحافة 5 دقائق','انزل الماء من السلم ببطء','قف في المنطقة الضحلة وتعوّد على حرارة الماء'],
 array['Prepare your kit: swimsuit, goggles and cap','Warm up on the deck for 5 minutes','Enter slowly using the ladder','Stand in the shallow end and get used to the temperature'],
 array['لا تقارن نفسك بالآخرين','ابدأ دائماً في المنطقة الضحلة'], array['Do not compare yourself to others','Always start in the shallow end'],1,true),
('e5500000-0000-4000-8000-000000000002','الثقة بالماء','Water Confidence','smile','https://images.unsplash.com/photo-1564415637254-92c66292cd64?auto=format&fit=crop&w=1000&q=80',
 'تمارين بسيطة لإزالة الخوف وبناء الراحة داخل الماء.','Simple exercises to remove fear and build comfort in the water.','beginner',30,
 array['امشِ داخل الماء ممسكاً بالحافة','ضع وجهك في الماء لثانيتين','انفخ فقاعات من الأنف والفم','اجلس تحت الماء والمس القاع'],
 array['Walk in the water holding the edge','Put your face in for two seconds','Blow bubbles through nose and mouth','Sit under water and touch the bottom'],
 array['تنفّس ببطء وهدوء','كرر التمرين حتى يصبح عادياً'], array['Breathe slowly and calmly','Repeat until it feels normal'],2,true),
('e5500000-0000-4000-8000-000000000003','التنفس الصحيح','Proper Breathing','wind','https://images.unsplash.com/photo-1530549387789-4c1017266635?auto=format&fit=crop&w=1000&q=80',
 'الزفير تحت الماء والشهيق السريع هو مفتاح السباحة المريحة.','Exhaling underwater and inhaling quickly is the key to relaxed swimming.','beginner',30,
 array['خذ شهيقاً من الفم فوق الماء','أنزل وجهك وأخرج الزفير ببطء','ارفع رأسك أو أدره جانباً للشهيق','كرر 10 مرات بإيقاع ثابت'],
 array['Inhale through the mouth above water','Lower your face and exhale slowly','Lift or turn your head to inhale','Repeat 10 times with a steady rhythm'],
 array['لا تحبس نفسك تحت الماء','الزفير الكامل يسهل الشهيق'], array['Never hold your breath underwater','A full exhale makes inhaling easier'],3,true),
('e5500000-0000-4000-8000-000000000004','أساليب الطفو','Floating Techniques','life-buoy','https://images.unsplash.com/photo-1438029071396-1e831a7fa6d8?auto=format&fit=crop&w=1000&q=80',
 'تعلّم الطفو على البطن والظهر بوضعية مسترخية.','Learn to float on your front and back in a relaxed position.','beginner',40,
 array['امسك الحافة ومد جسمك على البطن','اترك الحافة وافرد ذراعيك','للطفو على الظهر: ارفع الصدر وأرخِ الرأس للخلف','حافظ على الأذنين داخل الماء'],
 array['Hold the edge and stretch out on your front','Let go and extend your arms','For back float: lift your chest and relax your head back','Keep your ears in the water'],
 array['الاسترخاء يساعد على الطفو','افرد الذراعين والرجلين كنجمة'], array['Relaxation helps you float','Spread arms and legs like a star'],4,true),
('e5500000-0000-4000-8000-000000000005','وضعية الجسم','Body Position','move-horizontal','https://images.unsplash.com/photo-1519315901367-f34ff9154487?auto=format&fit=crop&w=1000&q=80',
 'جسم أفقي ومستقيم يعني مقاومة أقل وسرعة أكبر.','A flat, straight body means less drag and more speed.','beginner',30,
 array['ادفع من الحائط بوضعية السهم','انظر إلى القاع وليس للأمام','حافظ على الوركين قريبين من السطح','شد عضلات البطن قليلاً'],
 array['Push off the wall in a streamline','Look at the bottom, not forward','Keep your hips near the surface','Lightly engage your core'],
 array['الرأس المرفوع يُغرق الرجلين','ابقَ طويلاً كالسهم'], array['A raised head sinks your legs','Stay long like an arrow'],5,true),
('e5500000-0000-4000-8000-000000000006','السباحة الحرة','Freestyle','waves','https://images.unsplash.com/photo-1530549387789-4c1017266635?auto=format&fit=crop&w=1000&q=80',
 'أسرع الأساليب وأكثرها استخداماً: الذراعان، الرجلان، والتنفس الجانبي.','The fastest and most common stroke: arms, kick and side breathing.','beginner',90,
 array['ركلات رجلين سريعة من الورك','سحب الذراع تحت الجسم حتى الفخذ','استرجاع الذراع فوق الماء بمرفق مرتفع','التنفس الجانبي كل 2 أو 3 ضربات'],
 array['Quick kicks from the hips','Pull the arm under your body to the thigh','Recover the arm above water with a high elbow','Breathe to the side every 2 or 3 strokes'],
 array['دوّر جسمك مع كل ضربة','لا ترفع رأسك للأمام'], array['Rotate your body with each stroke','Do not lift your head forward'],6,true),
('e5500000-0000-4000-8000-000000000007','سباحة الظهر','Backstroke','rotate-ccw','https://images.unsplash.com/photo-1600965962361-9035dbfd1c50?auto=format&fit=crop&w=1000&q=80',
 'السباحة على الظهر مع تنفس حر وحركة ذراعين متناوبة.','Swimming on your back with free breathing and alternating arms.','intermediate',90,
 array['استلقِ على ظهرك والوجه للأعلى','ركلات مستمرة من الورك','دخول الذراع بالخنصر أولاً','دوران الكتفين مع كل ضربة'],
 array['Lie on your back, face up','Continuous kicks from the hips','Enter the water little finger first','Roll your shoulders with each stroke'],
 array['عدّ الضربات لمعرفة نهاية الحمام','ثبّت الرأس'], array['Count strokes to know where the wall is','Keep your head still'],7,true),
('e5500000-0000-4000-8000-000000000008','سباحة الصدر','Breaststroke','circle-dot','https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1000&q=80',
 'الأسلوب الأكثر تحكماً: سحب، تنفس، ركلة، انزلاق.','The most controlled stroke: pull, breathe, kick, glide.','intermediate',90,
 array['اسحب الذراعين للخارج ثم للداخل','ارفع الرأس للشهيق أثناء السحب','اضم القدمين واركل للخارج والخلف','انزلق بجسم مستقيم'],
 array['Pull arms out then in','Lift your head to breathe during the pull','Draw the feet up and kick out and back','Glide with a straight body'],
 array['التوقيت أهم من القوة','لا تهمل الانزلاق'], array['Timing beats power','Do not skip the glide'],8,true),
('e5500000-0000-4000-8000-000000000009','سباحة الفراشة','Butterfly','feather','https://images.unsplash.com/photo-1560090995-01632a28895b?auto=format&fit=crop&w=1000&q=80',
 'أصعب الأساليب: حركة تموجية للجسم مع ذراعين متزامنتين.','The most demanding stroke: a body wave with simultaneous arms.','advanced',120,
 array['تعلم حركة الدولفين بالجسم','ركلتان لكل دورة ذراعين','استرجاع الذراعين معاً فوق الماء','تنفس للأمام بارتفاع بسيط'],
 array['Learn the dolphin body wave','Two kicks per arm cycle','Recover both arms together over the water','Breathe forward with a low lift'],
 array['الإيقاع أهم من القوة','ابدأ بمسافات قصيرة'], array['Rhythm matters more than strength','Start with short distances'],9,true),
('e5500000-0000-4000-8000-000000000010','السلامة في السباحة','Swimming Safety','shield-check','https://images.unsplash.com/photo-1575429198097-0414ec08e8cd?auto=format&fit=crop&w=1000&q=80',
 'قواعد ذهبية للأمان داخل حمام السباحة وفي البحر.','Golden safety rules in the pool and at sea.','all',25,
 array['اسبح دائماً بوجود منقذ','تعرّف على عمق المياه','عند التعب: انقلب على ظهرك واطفُ','اطلب المساعدة برفع الذراع'],
 array['Always swim where a lifeguard is present','Know the water depth','When tired: turn onto your back and float','Raise your arm to call for help'],
 array['لا تقفز في مياه مجهولة العمق','راقب الأطفال باستمرار'], array['Never dive into water of unknown depth','Watch children at all times'],10,true),
('e5500000-0000-4000-8000-000000000011','أخطاء المبتدئين الشائعة','Common Beginner Mistakes','alert-triangle','https://images.unsplash.com/photo-1519315901367-f34ff9154487?auto=format&fit=crop&w=1000&q=80',
 'تعرّف على الأخطاء الأكثر تكراراً وكيف تتجنبها.','The most frequent mistakes and how to avoid them.','beginner',20,
 array['رفع الرأس للأمام أثناء الحرة','حبس النفس تحت الماء','ركل الرجلين من الركبة','السرعة على حساب التقنية'],
 array['Lifting the head forward in freestyle','Holding the breath underwater','Kicking from the knees','Rushing instead of focusing on technique'],
 array['صوّر نفسك وراجع الفيديو','اطلب ملاحظات من المدرب'], array['Film yourself and review','Ask your coach for feedback'],11,true),
('e5500000-0000-4000-8000-000000000012','نصائح احترافية','Professional Swimming Tips','trophy','https://images.unsplash.com/photo-1530549387789-4c1017266635?auto=format&fit=crop&w=1000&q=80',
 'أسرار السباحين المحترفين لتحسين الأداء.','Secrets professional swimmers use to improve performance.','advanced',30,
 array['ركّز على عدد الضربات لكل طول','تمرّن بفترات متنوعة الشدة','قوِّ عضلات الجذع خارج الماء','اهتم بالنوم والتغذية'],
 array['Track strokes per length','Train with varied-intensity intervals','Build core strength on dry land','Prioritise sleep and nutrition'],
 array['الاستمرارية أهم من الشدة','سجّل أزمنتك أسبوعياً'], array['Consistency beats intensity','Log your times weekly'],12,true),
('e5500000-0000-4000-8000-000000000013','ضربات الرجلين','Kicking Technique','footprints','https://images.unsplash.com/photo-1600965962361-9035dbfd1c50?auto=format&fit=crop&w=1000&q=80',
 'ركلات فعّالة تدفعك للأمام وتحافظ على توازنك.','Efficient kicks that drive you forward and keep you balanced.','beginner',30,
 array['امسك اللوح وافرد ذراعيك','اركل من الورك بركبة مرنة','القدمان ممدودتان كالزعانف','ركلات صغيرة وسريعة'],
 array['Hold a kickboard with straight arms','Kick from the hip with soft knees','Point your toes like fins','Small, fast kicks'],
 array['الرجلان لا تخرجان كثيراً من الماء'], array['Feet should barely break the surface'],13,true),
('e5500000-0000-4000-8000-000000000014','الطفو العمودي','Treading Water','anchor','https://images.unsplash.com/photo-1438029071396-1e831a7fa6d8?auto=format&fit=crop&w=1000&q=80',
 'البقاء في مكانك في المياه العميقة بأقل مجهود.','Staying in place in deep water with minimal effort.','intermediate',40,
 array['حافظ على الجسم عمودياً','حرّك اليدين أفقياً كأنك تمسح الطاولة','ركلة الدراجة أو ركلة الصدر','تنفّس بهدوء'],
 array['Keep your body vertical','Scull your hands horizontally','Use a cycling or breaststroke kick','Breathe calmly'],
 array['مهارة أساسية للنجاة','تدرّب بجانب الحافة أولاً'], array['A core survival skill','Practise next to the wall first'],14,true),
('e5500000-0000-4000-8000-000000000015','الدوران والدفع من الحائط','Turns & Push-offs','repeat','https://images.unsplash.com/photo-1519315901367-f34ff9154487?auto=format&fit=crop&w=1000&q=80',
 'دورانات سريعة ودفع قوي لتوفير الوقت والجهد.','Fast turns and powerful push-offs to save time and energy.','advanced',60,
 array['اقترب من الحائط دون إبطاء','الدوران المفتوح للصدر والفراشة','الدوران الانقلابي للحرة والظهر','ادفع بوضعية السهم وانزلق'],
 array['Approach the wall without slowing','Open turn for breaststroke and butterfly','Flip turn for freestyle and backstroke','Push off in a streamline and glide'],
 array['أخرج الهواء من الأنف أثناء الانقلاب'], array['Exhale through your nose during the flip'],15,true)
on conflict (id) do nothing;

