-- ---------- equipment -------------------------------------------------
insert into public.equipment (name_ar, name_en, description_ar, description_en, icon, category, sort_order, is_demo) values
('مايوه سباحة','Swimsuit','مايوه رياضي مريح ومناسب للتدريب (يفضل من الليكرا).','A comfortable athletic training swimsuit (lycra preferred).','shirt','essential',1,true),
('نظارة سباحة','Swimming Goggles','نظارة مناسبة لمقاس الوجه لا يدخلها الماء.','Well-fitting goggles that keep water out.','glasses','essential',2,true),
('غطاء رأس','Swimming Cap','غطاء سيليكون يحمي الشعر ويحافظ على نظافة الحمام.','A silicone cap to protect hair and keep the pool clean.','hard-hat','essential',3,true),
('فوطة','Towel','فوطة سريعة الجفاف للاستخدام بعد التمرين.','A quick-dry towel for after training.','layers','essential',4,true),
('شبشب سباحة','Pool Slippers','شبشب مانع للانزلاق للمشي حول حمام السباحة.','Non-slip slippers for walking on the pool deck.','footprints','essential',5,true),
('زجاجة مياه','Water Bottle','للحفاظ على الترطيب أثناء وبعد التمرين.','Stay hydrated during and after training.','glass-water','essential',6,true),
('لوح الركلات','Kickboard','أداة مساعدة لتمارين الرجلين (متوفرة في معظم الحمامات).','A training aid for kick drills (available at most pools).','rectangle-horizontal','recommended',7,true),
('زعانف قصيرة وسدادات أذن','Short Fins & Ear Plugs','زعانف لتقوية الرجلين وسدادات لمن يعاني من حساسية الأذن.','Fins to build leg strength, ear plugs for sensitive ears.','plus-circle','recommended',8,true);

