-- ---------- reviews (12, demo — not genuine endorsements) -------------
insert into public.reviews (customer_name, rating, text_ar, text_en, course_id, review_date, status, source, sort_order, is_demo) values
('أم يوسف (تجريبي)',5,'ابني كان خايف جداً من الماء، وبعد شهر واحد أصبح يسبح وحده. أسلوب الكابتن هادئ وصبور.','My son was very afraid of water; after one month he swims on his own. The coach is calm and patient.','c0000000-0000-4000-8000-000000000004',current_date - 10,'approved','admin',1,true),
('سارة خ. (تجريبي)',5,'تعلمت السباحة في عمر 27 سنة وما كنت متخيلة إن ده ممكن. شكراً كابتن أمير!','I learned to swim at 27 and never imagined it was possible. Thank you Captain Amir!','c0000000-0000-4000-8000-000000000005',current_date - 18,'approved','admin',2,true),
('Karim N. (Demo)',5,'تحسن كبير في أسلوب السباحة الحرة والتنفس خلال 6 أسابيع فقط.','Huge improvement in my freestyle and breathing in just 6 weeks.','c0000000-0000-4000-8000-000000000002',current_date - 25,'approved','admin',3,true),
('والد ملك (تجريبي)',4,'تنظيم ممتاز ومتابعة مستمرة مع أولياء الأمور. ننتظر المستوى التالي.','Excellent organisation and constant follow-up with parents. Looking forward to the next level.','c0000000-0000-4000-8000-000000000004',current_date - 30,'approved','admin',4,true),
('هبة س. (تجريبي)',5,'الدروس الخاصة ساعدتني أتغلب على خوفي تماماً.','Private lessons helped me completely overcome my fear.','c0000000-0000-4000-8000-000000000006',current_date - 41,'approved','admin',5,true),
('زياد ش. (تجريبي)',5,'برنامج التدريب الاحترافي حسّن زمني في 100 متر حرة بشكل واضح.','The professional program clearly improved my 100m freestyle time.','c0000000-0000-4000-8000-000000000007',current_date - 47,'approved','admin',6,true),
('Laila M. (Demo)',5,'تجربة رائعة، الحمام نظيف والمواعيد مناسبة للعمل.','Great experience — clean pool and work-friendly times.','c0000000-0000-4000-8000-000000000005',current_date - 55,'approved','admin',7,true),
('أم جنى (تجريبي)',5,'كورس الأمان في الماء ضروري لكل طفل. بنتي تعرف الآن كيف تطفو على ظهرها.','The water safety course is a must for every child. My daughter now knows how to back-float.','c0000000-0000-4000-8000-000000000008',current_date - 60,'approved','admin',8,true),
('محمود ف. (تجريبي)',4,'في عمر 63 تعلمت السباحة بأمان. شكراً على الصبر.','At 63 I learned to swim safely. Thank you for the patience.','c0000000-0000-4000-8000-000000000005',current_date - 70,'approved','admin',9,true),
('Adam K. (Demo)',5,'ابني يحب التمرين وينتظره كل أسبوع!','My son loves training and looks forward to it every week!','c0000000-0000-4000-8000-000000000004',current_date - 82,'approved','admin',10,true),
('ريم ع. (تجريبي)',5,'أخيراً فهمت سباحة الصدر بشكل صحيح.','I finally understand breaststroke properly.','c0000000-0000-4000-8000-000000000002',current_date - 3,'pending','website',11,true),
('عمر ح. (تجريبي)',4,'مدرب ممتاز، أتمنى زيادة عدد المواعيد المسائية.','Excellent coach — I wish there were more evening slots.','c0000000-0000-4000-8000-000000000001',current_date - 1,'pending','website',12,true);

-- ---------- FAQs (10) -------------------------------------------------
insert into public.faqs (question_ar, question_en, answer_ar, answer_en, sort_order, is_demo) values
('من أي عمر يمكن للأطفال البدء في تعلم السباحة؟','At what age can children start swimming?','يمكن البدء من عمر 3 سنوات في برامج الثقة بالماء، ومن 4 إلى 5 سنوات في كورسات تعليم السباحة المنظمة.','Children can start water-confidence programs from age 3, and structured learn-to-swim courses from ages 4–5.',1,true),
('هل يمكن للكبار تعلم السباحة من الصفر؟','Can adults learn swimming from zero?','بالتأكيد. لدينا برنامج خاص بالكبار يبدأ بالتغلب على الخوف ويتدرج حتى السباحة بثقة.','Absolutely. Our adult program starts with overcoming fear and progresses step by step to confident swimming.',2,true),
('ما الأدوات التي أحتاجها؟','What equipment do I need?','مايوه، نظارة سباحة، غطاء رأس، فوطة، شبشب، وزجاجة مياه. التفاصيل في قسم المتطلبات.','A swimsuit, goggles, cap, towel, slippers and a water bottle. See the Requirements section for details.',3,true),
('كم من الوقت يستغرق تعلم السباحة؟','How long does it take to learn swimming?','يختلف حسب العمر والانتظام، لكن معظم المبتدئين يسبحون 25 متراً خلال 12 إلى 16 حصة.','It depends on age and consistency, but most beginners can swim 25m within 12–16 sessions.',4,true),
('هل تتوفر دروس خاصة؟','Are private lessons available?','نعم، تتوفر دروس فردية مع كابتن أمير بمواعيد مرنة لكل الأعمار والمستويات.','Yes, one-to-one lessons with Captain Amir are available with flexible times for all ages and levels.',5,true),
('أين تُقام التدريبات؟','Where are training sessions held?','في عدة حمامات سباحة مجهزة. راجع قسم أماكن التدريب لمعرفة العناوين والمواعيد.','At several well-equipped pools. See the Training Locations section for addresses and hours.',6,true),
('كيف أحجز درساً؟','How can I book a lesson?','املأ نموذج التسجيل أو تواصل عبر واتساب. سيتواصل معك الفريق لتأكيد الحجز بعد المراجعة.','Fill in the registration form or message us on WhatsApp. The team will contact you to confirm after review.',7,true),
('هل يمكنني تغيير موعد التدريب؟','Can I change my training schedule?','نعم، يمكن تغيير الموعد حسب توفر الأماكن في المواعيد الأخرى بالتنسيق مع الإدارة.','Yes, you can switch slots depending on availability in other sessions, in coordination with the team.',8,true),
('هل المياه مُدفأة؟','Is the pool water heated?','بعض المواقع بها حمامات مُدفأة. تجد التفاصيل في مرافق كل موقع.','Some locations have heated pools. Check each location''s facilities.',9,true),
('ما سياسة الإلغاء والتعويض؟','What is the cancellation and make-up policy?','يمكن تعويض الحصة عند الإبلاغ قبل 24 ساعة على الأقل (سياسة تجريبية).','A session can be made up if you notify us at least 24 hours in advance (demo policy).',10,true);
